package com.narudzbine.identity.infrastructure.web;

import com.narudzbine.catalogue.api.*;
import com.narudzbine.catalogue.api.VendorProducts.*;
import com.narudzbine.identity.api.*;
import com.narudzbine.identity.application.*;
import com.narudzbine.organizations.api.*;
import com.narudzbine.shared.api.ResourceRevisions;
import jakarta.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.util.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.ResponseEntity;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/catalogue/products")
@ConditionalOnProperty(name="identity.http.enabled",havingValue="true")
public final class ProductController {
    private final SessionService sessions;private final MembershipAccess memberships;private final BusinessAuthorization authorization;private final VendorProducts products;private final com.narudzbine.pricing.api.BasePricing pricing;
    private final SessionTransportPolicy policy;private final LoginThrottle throttle;private final ResourceRevisions revisions;private final TransactionTemplate transaction;private final byte[] creationKey;
    ProductController(SessionService sessions,MembershipAccess memberships,BusinessAuthorization authorization,VendorProducts products,com.narudzbine.pricing.api.BasePricing pricing,SessionTransportPolicy policy,LoginThrottle throttle,ResourceRevisions revisions,PlatformTransactionManager manager,@org.springframework.beans.factory.annotation.Value("${identity.http.revision-key}")String key){this.sessions=sessions;this.memberships=memberships;this.authorization=authorization;this.products=products;this.pricing=pricing;this.policy=policy;this.throttle=throttle;this.revisions=revisions;this.creationKey=Base64.getDecoder().decode(key);transaction=new TransactionTemplate(manager);transaction.setTimeout(10);}
    @GetMapping Page list(HttpServletRequest request){AuthController.noBody(request);var query=ProductRequests.query(request);var selected=policy.select(request);admit(selected,false);return transaction.execute(status->{var scope=scope(selected,false,null);var page=products.list(scope.organizationId(),query);activity(selected);return new Page(page.items().stream().map(this::response).toList(),query.page(),query.size(),page.total());});}
    @GetMapping("/{productId}") Result get(@PathVariable String productId,HttpServletRequest request){AuthController.noQuery(request);AuthController.noBody(request);UUID id=ContactRequests.id(productId,"PATH","productId");var selected=policy.select(request);admit(selected,false);return transaction.execute(status->{var scope=scope(selected,false,null);var result=products.read(scope.organizationId(),id);activity(selected);return response(result);});}
    @PostMapping ResponseEntity<Result> create(HttpServletRequest request)throws IOException{AuthController.noQuery(request);var selected=policy.select(request);String csrf=csrf(request,selected);var input=ProductRequests.input(request,true);admit(selected,true);return transaction.execute(status->{var scope=scope(selected,true,csrf);var created=products.create(scope.accountId(),scope.organizationId(),input.id(),input.values(),ProductRequests.digest(input.values(),creationKey));activity(selected);return ResponseEntity.status(created.replay()?200:201).header("Location","/api/v1/catalogue/products/"+input.id()).body(response(created.item()));});}
    @PutMapping("/{productId}") Result update(@PathVariable String productId,HttpServletRequest request)throws IOException{AuthController.noQuery(request);UUID id=ContactRequests.id(productId,"PATH","productId");var selected=policy.select(request);String csrf=csrf(request,selected);var input=ProductRequests.input(request,false);admit(selected,true);return transaction.execute(status->{var scope=scope(selected,true,csrf);var current=products.read(scope.organizationId(),id);revision(current,input.expectedRevision());if(input.pricingCorrection()!=null){authorization.require(scope.accountId(),scope.organizationId(),scope.country(),BusinessCapability.EDIT_PRICES);var correction=input.pricingCorrection();var before=pricing.read(scope.organizationId(),id);PricingController.requireRevision(revisions,before,correction.expectedRevision());boolean publicationChanged=correction.deactivateProduct()&&current.state().equals("ACTIVE");if(publicationChanged){products.publication(scope.accountId(),scope.organizationId(),id,false);}try{pricing.replace(scope.accountId(),scope.organizationId(),id,before.revision(),correction.values(),input.values().minimumQuantity(),input.values().quantityStep(),publicationChanged);}catch(com.narudzbine.pricing.api.PricingFailure failure){if(failure.reason()==com.narudzbine.pricing.api.PricingFailure.Reason.INVALID_SCHEDULE){throw new AuthHttpFailure(failure.fields().stream().map(field->new AuthErrors.FieldError("/pricingCorrection"+field,"INVALID_VALUE")).toList());}throw failure;}}var result=products.replace(scope.accountId(),scope.organizationId(),id,input.values());activity(selected);return response(result);});}
    @PutMapping("/{productId}/gallery") Result gallery(@PathVariable String productId,HttpServletRequest request)throws IOException{
        AuthController.noQuery(request);UUID id=ContactRequests.id(productId,"PATH","productId");var selected=policy.select(request);String csrf=csrf(request,selected);var input=ProductRequests.gallery(request);admit(selected,true);
        return transaction.execute(status->{var scope=scope(selected,true,csrf);var current=products.read(scope.organizationId(),id);revision(current,input.expectedRevision());var result=products.gallery(scope.accountId(),scope.organizationId(),id,input.assetIds());activity(selected);return response(result);});
    }
    @PostMapping("/{productId}/activate") Result activate(@PathVariable String productId,HttpServletRequest request)throws IOException{return publication(productId,request,true);}
    @PostMapping("/{productId}/deactivate") Result deactivate(@PathVariable String productId,HttpServletRequest request)throws IOException{return publication(productId,request,false);}
    private Result publication(String productId,HttpServletRequest request,boolean active)throws IOException{AuthController.noQuery(request);UUID id=ContactRequests.id(productId,"PATH","productId");var selected=policy.select(request);String csrf=csrf(request,selected),expected=ContactRequests.revisionCommand(request);admit(selected,true);return transaction.execute(status->{var scope=scope(selected,true,csrf);var current=products.read(scope.organizationId(),id);revision(current,expected);var result=products.publication(scope.accountId(),scope.organizationId(),id,active);activity(selected);return response(result);});}
    @PostMapping("/{productId}/archive") Result archive(@PathVariable String productId,HttpServletRequest request)throws IOException{return state(productId,request,true);}
    @PostMapping("/{productId}/restore") Result restore(@PathVariable String productId,HttpServletRequest request)throws IOException{return state(productId,request,false);}
    private Result state(String productId,HttpServletRequest request,boolean archived)throws IOException{AuthController.noQuery(request);UUID id=ContactRequests.id(productId,"PATH","productId");var selected=policy.select(request);String csrf=csrf(request,selected),expected=ContactRequests.revisionCommand(request);admit(selected,true);return transaction.execute(status->{var scope=scope(selected,true,csrf);var current=products.read(scope.organizationId(),id);revision(current,expected);var result=products.state(scope.accountId(),scope.organizationId(),id,archived);activity(selected);return response(result);});}
    @PutMapping("/{productId}/featured") Result featured(@PathVariable String productId,HttpServletRequest r)throws IOException{AuthController.noQuery(r);UUID id=ContactRequests.id(productId,"PATH","productId");var body=AuthRequests.object(r,Set.of("expectedRevision","featured"));String expected=ContactRequests.revision(body);if(!body.path("featured").isBoolean())throw new AuthHttpFailure(422,"VALIDATION_FAILED","/featured");boolean featured=body.path("featured").asBoolean();var selected=policy.select(r);String csrf=csrf(r,selected);admit(selected,true);return transaction.execute(status->{var scope=scope(selected,true,csrf);var old=products.read(scope.organizationId(),id);revision(old,expected);var item=products.featured(scope.accountId(),scope.organizationId(),id,featured);activity(selected);return response(item);});}
    private void revision(Item current,String expected){if(!revisions.matches("product/v1",current.id(),current.revision(),expected)){throw new RevisionConflict(revisions.encode("product/v1",current.id(),current.revision()));}}
    private BusinessScope scope(SessionTransportPolicy.Selected selected,boolean write,String csrf){var principal=write?sessions.authenticateForOrganizationWrite(selected.secret(),selected.transport()):sessions.authenticate(selected.secret(),selected.transport());if(write&&selected.transport()==SessionTransport.BROWSER){sessions.requireCsrf(selected.secret(),csrf);}var member=memberships.lockForAuthorization(principal.accountId()).orElseThrow(()->new BusinessAccessDenied(BusinessAccessDenied.Reason.INACCESSIBLE_SCOPE));if(member.type()!=OrganizationType.VENDOR){throw new BusinessAccessDenied(BusinessAccessDenied.Reason.INACCESSIBLE_SCOPE);}return authorization.require(principal.accountId(),member.organizationId(),member.country(),BusinessCapability.EDIT_CATALOGUE);}
    private void admit(SessionTransportPolicy.Selected selected,boolean write){UUID account=transaction.execute(s->write?sessions.authenticate(selected.secret(),selected.transport()).accountId():sessions.replayAdmissionAccount(selected.secret(),selected.transport()));throttle.admitApi(account,write);}
    private void activity(SessionTransportPolicy.Selected selected){sessions.recordSuccessfulActivity(selected.secret(),selected.transport());}
    private static String csrf(HttpServletRequest request,SessionTransportPolicy.Selected selected){return selected.transport()==SessionTransport.BROWSER?AuthController.csrfHeader(request):null;}
    private Result response(Item p){return ProductResponses.result(p,revisions);}

    record Result(UUID id,String revision,String sku,String name,String description,UUID unitId,String packDescription,UUID categoryId,List<UUID> tagIds,int minimumQuantity,int quantityStep,String state,boolean featured,boolean unitAndPackFrozen,List<UUID> galleryAssetIds,String createdAt,String updatedAt){ }
    record Page(List<Result> items,int page,int size,Long total){ }
}
